\title{Existence of Non-Trivial Boolean Degree One Functions \\
on the Grassmann Scheme $J_q(4,2)$}
\author{Aristotle}
\date{2026-06-24}

\begin{document}
\maketitle

\begin{abstract}
A \emph{Boolean degree one function} on the Grassmann scheme $J_q(4,2)$ --- equivalently
a \emph{Cameron--Liebler line class} of the projective space $\PG(3,q)$ --- is a
$\{0,1\}$-valued function on the lines whose expansion in the eigenspaces of the
Grassmann graph is supported on the first two layers. Every such function carries an
integer \emph{parameter} $x$ with $0 \le x \le q^2+1$, and its support has exactly
$x\,(q^2+q+1)$ lines. Eight functions are \emph{trivial} (built from point-pencils and
plane-pencils): the constants $0,1$ and the four $\pm$ combinations of one point- and
one plane-pencil, whose parameters fill the set $\{0,1,2,q^2-1,q^2,q^2+1\}$. We isolate
and prove the unconditional \textbf{arithmetic core} of the Bruen--Drudge
self-complementary construction. Define the midpoint parameter
$\bdParam(q)=\lfloor (q^2+1)/2\rfloor$. We prove (i) for odd $q$,
$2\bdParam(q)=q^2+1$, so the midpoint is a genuine integer and is self-complementary;
(ii) for $q\ge 3$, $2<\bdParam(q)<q^2-1$, so the midpoint lies strictly inside the
non-trivial parameter window. We then formalize the conditional consequence: any
Cameron--Liebler class realized at parameter $\bdParam(q)$ on the genuine line set of
$J_q(4,2)$ (with $q\ge 3$) has a \emph{non-constant} indicator function, and hence is a
non-trivial Boolean degree one function. The geometric realizability (the Bruen--Drudge
theorem) is carried as an explicit hypothesis rather than re-derived, so the proof
cleanly separates number theory from geometry. All results have been formally verified.
\end{abstract}

\textbf{Keywords:} Cameron--Liebler line class, Grassmann scheme $J_q(4,2)$, Boolean
degree one function, Bruen--Drudge construction, self-complementary, projective space
$\PG(3,q)$, $q$-Krawtchouk, association scheme.

\section{Introduction}

\subsection{Setting}
Let $\Fq$ be the finite field with $q$ elements ($q$ a prime power), and let
$V=\Fq^4$. The \textbf{Grassmann scheme} $J_q(4,2)$ is the association scheme whose
points are the $2$-dimensional subspaces of $V$ --- equivalently, the \emph{lines} of
the projective space $\PG(3,q)$ --- with relations determined by the dimension of the
intersection of two subspaces. Its underlying graph, the \textbf{Grassmann graph},
joins two lines when they meet in a point.

A function $f:\{\text{lines}\}\to\{0,1\}$ is a \textbf{Boolean degree one function} if,
in the orthogonal eigenspace decomposition associated to the scheme, $f$ has nonzero
components only in the trivial eigenspace $V_0$ and the first eigenspace $V_1$. These
functions coincide exactly with the indicator functions of \textbf{Cameron--Liebler
line classes} (Cameron and Liebler, 1982).

\subsection{The parameter and the trivial classes}
Every Cameron--Liebler line class $L$ has an integer \textbf{parameter} $x=x(L)$ with
$0\le x\le q^2+1$, and
\[
|L| \;=\; x\,(q^2+q+1),
\]
i.e.\ the size of the class is $x$ times the number of lines through a point. This
\emph{degree-one counting identity} is the combinatorial signature used throughout.

Eight classes are constructible directly from incidence geometry and are deemed
\textbf{trivial}: the empty class ($x=0$), all lines ($x=q^2+1$), a point-pencil $x_p$
($x=1$) and its complement ($x=q^2$), a plane-pencil $y_r$ ($x=1$) and its complement
($x=q^2$), the sum $x_p+y_r$ with $p\notin r$ ($x=2$) and its complement ($x=q^2-1$).
Their parameters form the \textbf{trivial set}
\[
T_q \;=\; \{\,0,\,1,\,2,\,q^2-1,\,q^2,\,q^2+1\,\},
\]
invariant under the complementation involution $x\mapsto q^2+1-x$. The motivating
problem: \emph{does a Boolean degree one function exist whose parameter lies strictly
inside the open window $(2,q^2-1)$?} Such a function is \emph{non-trivial}.

\subsection{Contribution}
We isolate the unconditional arithmetic skeleton of the Bruen--Drudge construction and
formally verify it, then connect it to non-triviality through a minimal,
hypothesis-driven model of a Cameron--Liebler class.

\section{Foundational line counts}
We work over $\mathbb{N}$ throughout.

\begin{definition}[lines through a point]
The number of lines of $\PG(3,q)$ through a fixed point is
$\numLTP(q)=q^2+q+1$.
\end{definition}
\emph{Justification.} The lines through a fixed point $p$ correspond to the $1$-spaces
of $V/\langle p\rangle\cong\Fq^3$, i.e.\ the points of $\PG(2,q)$, of which there are
$q^2+q+1$.

\begin{definition}[total lines]
The total number of lines of $\PG(3,q)$ is the Gaussian binomial coefficient
\[
\numLines(q)=\binom{4}{2}_q=(q^2+1)(q^2+q+1).
\]
\end{definition}
\emph{Justification.} $\binom{4}{2}_q=\frac{(q^4-1)(q^3-1)}{(q^2-1)(q-1)}
=(q^2+1)(q^2+q+1)$.

\begin{lemma}[positivity]
$\numLTP(q)>0$ and $\numLines(q)>0$ for all $q$.
\end{lemma}

\section{The Bruen--Drudge midpoint parameter}

\begin{definition}
The \textbf{Bruen--Drudge parameter} is
$\bdParam(q)=\left\lfloor (q^2+1)/2\right\rfloor$ (natural-number division). A class
with parameter $x$ is congruent to its complement (parameter $q^2+1-x$) iff $2x=q^2+1$,
i.e.\ $x=(q^2+1)/2$.
\end{definition}

\subsection{Integrality for odd $q$}

\begin{theorem}[\texttt{bdParam\_two\_mul}]
If $q$ is odd, then $2\,\bdParam(q)=q^2+1$.
\end{theorem}
\begin{proof}[Proof sketch]
If $q$ is odd then $q^2$ is odd, so $q^2+1$ is even and $2\mid(q^2+1)$. For an even
$m$, $2\lfloor m/2\rfloor=m$; apply with $m=q^2+1$.
\end{proof}

\begin{corollary}[\texttt{bdParam\_self\_complement}]
If $q$ is odd, then $\bdParam(q)+\bdParam(q)=q^2+1$, so the parameter is
self-complementary under $x\mapsto q^2+1-x$.
\end{corollary}

\begin{remark}[even $q$ obstruction]
For even $q$, $q^2+1$ is odd, so $2\nmid(q^2+1)$ and
$2\lfloor(q^2+1)/2\rfloor=q^2\ne q^2+1$. Thus there is \emph{no} integer
self-complementary parameter when $q$ is even; e.g.\ $q=4$ gives $q^2+1=17$ and
$2\cdot 8=16$.
\end{remark}

\subsection{Non-triviality bounds for $q\ge 3$}

\begin{theorem}[lower bound, \texttt{bdParam\_gt\_two}]
For $q\ge 3$, $\;2<\bdParam(q)$.
\end{theorem}
\begin{proof}[Proof sketch]
$\lfloor m/2\rfloor\ge k+1\iff m\ge 2(k+1)$; here $q^2+1\ge 10>6$ for $q\ge 3$.
\end{proof}

\begin{theorem}[sharper lower bound, \texttt{bdParam\_gt\_four}]
For $q\ge 3$ with $q$ odd, $\;4<\bdParam(q)$.
\end{theorem}
\begin{proof}[Proof sketch]
Write $q=2k+1$; then $\bdParam(q)=2k^2+2k+1\ge 5$ for $k\ge 1$ (i.e.\ $q\ge 3$).
\end{proof}

\begin{theorem}[upper bound, \texttt{bdParam\_lt}]
For $q\ge 3$, $\;\bdParam(q)<q^2-1$.
\end{theorem}
\begin{proof}[Proof sketch]
$\lfloor(q^2+1)/2\rfloor\le(q^2+1)/2<q^2-1\iff q^2+1<2q^2-2\iff q^2>3$, true for
$q\ge 2$. Formally use $2\lfloor(q^2+1)/2\rfloor\le q^2+1$ and linear arithmetic.
\end{proof}

\begin{theorem}[non-triviality, \texttt{bdParam\_nontrivial}]
For $q\ge 3$, $\;2<\bdParam(q)<q^2-1$.
\end{theorem}

Hence for $q\ge 3$ the midpoint parameter lies strictly inside $(2,q^2-1)$ and avoids
$T_q$.

\subsection{The threshold at $q=3$}

\begin{proposition}[the $q=2$ obstruction]
The non-trivial window $(2,q^2-1)$ contains no integer iff $q\le 2$.
\end{proposition}
\emph{Discussion.} $(2,q^2-1)$ is non-empty iff $q^2>4$, i.e.\ $q\ge 3$. For $q=2$ the
range is $\{0,\dots,5\}$ and $T_2=\{0,1,2,3,4,5\}$ is everything; for $q=3$ the range
is $\{0,\dots,10\}$, $T_3=\{0,1,2,8,9,10\}$, and the window $\{3,4,5,6,7\}$ opens with
$\bdParam(3)=5$ inside.

\section{From parameter to non-constancy}

\begin{definition}[\texttt{CLClass}]
Fix $q\in\mathbb{N}$ and a finite type $\mathsf{lines}$ with decidable equality. A
\textbf{Cameron--Liebler class} is a triple
$C=(\mathrm{toFun},\mathrm{param},\mathrm{card\_eq})$ where
$\mathrm{toFun}:\mathsf{lines}\to\{\true,\false\}$ is the indicator,
$\mathrm{param}\in\mathbb{N}$, and $\mathrm{card\_eq}$ is the counting identity
\[
\bigl|\{\,l:\mathrm{toFun}(l)=\true\,\}\bigr|=\mathrm{param}\cdot\numLTP(q)
=\mathrm{param}\,(q^2+q+1).
\]
\end{definition}

\begin{theorem}[\texttt{CLClass.exists\_true}]
If $\mathrm{param}>0$, then $\mathrm{toFun}(l)=\true$ for some $l$.
\end{theorem}
\begin{proof}[Proof sketch]
If $\mathrm{toFun}\equiv\false$ the support is empty, so
$0=\mathrm{param}\,(q^2+q+1)>0$, a contradiction.
\end{proof}

\begin{theorem}[\texttt{CLClass.exists\_false}]
If $\#\,\mathsf{lines}=\numLines(q)$ and $\mathrm{param}<q^2+1$, then
$\mathrm{toFun}(l)=\false$ for some $l$.
\end{theorem}
\begin{proof}[Proof sketch]
Contrapositive: if $\mathrm{toFun}\equiv\true$ then
$(q^2+1)(q^2+q+1)=\mathrm{param}\,(q^2+q+1)$; cancel $q^2+q+1>0$ to get
$\mathrm{param}=q^2+1$, contradicting $\mathrm{param}<q^2+1$.
\end{proof}

\begin{theorem}[conditional non-triviality, \texttt{CLClass.toFun\_not\_constant}]
Let $q\ge 3$, $\#\,\mathsf{lines}=\numLines(q)$, and $\mathrm{param}=\bdParam(q)$. Then
$\mathrm{toFun}$ is non-constant:
\[
\bigl(\exists l,\ \mathrm{toFun}(l)=\true\bigr)\wedge
\bigl(\exists l,\ \mathrm{toFun}(l)=\false\bigr).
\]
\end{theorem}
\begin{proof}
$\bdParam(q)>2>0$ gives the first conjunct via the previous existence theorem;
$\bdParam(q)<q^2-1<q^2+1$ gives the second.
\end{proof}

\begin{corollary}[existence of a non-trivial Boolean degree one function]
For odd $q\ge 3$, granting the Bruen--Drudge realizability hypothesis (a
\texttt{CLClass} with parameter $\bdParam(q)$ on the genuine line set of $J_q(4,2)$
exists), its indicator is a non-constant Boolean degree one function whose parameter
lies strictly inside $(2,q^2-1)$ and hence outside $T_q$; it is therefore non-trivial,
and moreover self-complementary.
\end{corollary}

\section{Algorithms}

\subsection{Parameter-window classifier}
Given $q$, compute $T_q$, the window $(2,q^2-1)$, the midpoint $\bdParam(q)$, and decide
membership; $O(1)$ arithmetic.

\subsection{Non-constancy certificate}
Given a parameter $x$ and $N=\numLines(q)$, the support size $x\,(q^2+q+1)$ is forced;
the class has a $\true$ iff $x>0$ and a $\false$ iff $x<q^2+1$, so it is non-constant
iff $0<x<q^2+1$; $O(1)$.

